def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the color and locations of the full-width/full-height separators.
    lines = []
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            lines.append(grid[r][0])
    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            lines.append(grid[0][c])
    sep = max(set(lines), key=lines.count)

    hr = [r for r in range(h) if all(v == sep for v in grid[r])]
    vc = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def spans(size, dividers):
        bounds = [-1] + dividers + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_spans = spans(h, hr)
    col_spans = spans(w, vc)

    # The non-marker panel with the most colored cells contains the pattern.
    best = None
    best_count = -1
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            if ci == 0:
                continue
            cells = [(r - r0, c - c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep)]
            if len(cells) > best_count:
                best, best_count = (r1 - r0, c1 - c0, cells), len(cells)

    ph, pw, cells = best
    pattern = [(dr, dc) for dr, dc, _ in cells]

    out = [[sep if grid[r][c] == sep else 0 for c in range(w)] for r in range(h)]

    for r0, r1 in row_spans:
        # Marker color is read from the first panel of this panel row.
        colors = [grid[r][c] for r in range(r0, r1)
                  for c in range(col_spans[0][0], col_spans[0][1])
                  if grid[r][c] not in (0, sep)]
        if not colors:
            continue
        color = max(set(colors), key=colors.count)
        for c0, c1 in col_spans:
            for dr, dc in pattern:
                if dr < r1 - r0 and dc < c1 - c0:
                    out[r0 + dr][c0 + dc] = color

    return out
